#' Interrupted Time Series Analysis
#'
#' Evaluates the effect of an intervention on an outcome measured repeatedly 
#' over time using segmented regression of an interrupted time series. The 
#' model estimates the pre-intervention level and trend, the immediate change 
#' in level at the intervention point, and the change in trend (slope) 
#' afterwards. Standard errors can be adjusted for autocorrelation using 
#' Newey-West (HAC) estimators, and a Durbin-Watson test reports residual 
#' autocorrelation. This is the standard quasi-experimental design for 
#' evaluating quality-improvement, policy, or laboratory-process interventions 
#' where randomization is not possible.
#' 
#' @param data The data as a data frame (one row per time point).
#' @param time Sequential time index (e.g. month or week number), evenly
#'   spaced.
#' @param outcome The continuous outcome measured at each time point.
#' @param interventionTime The value of the time variable at which the
#'   intervention began. The first post-intervention observation is the first
#'   time point at or after this value.
#' @param hac Adjust standard errors for autocorrelation and
#'   heteroscedasticity using the Newey-West estimator. Recommended for time
#'   series data.
#' @param lag Maximum lag for the Newey-West estimator. Set to 0 to choose the
#'   lag automatically from the series length.
#' @param counterfactual Overlay the projected counterfactual (the
#'   pre-intervention trend extrapolated forward as if no intervention had
#'   occurred) on the plot.
#' @param predictAt A post-intervention time point at which to report the
#'   absolute and relative effect of the intervention (observed model prediction
#'   minus counterfactual). Set to 0 to skip.
#' @param showDiagnostics Report the Durbin-Watson test for residual
#'   autocorrelation.
#' @param showPlot Display the observed series with fitted segments and
#'   intervention marker.
#' @param showSummary Display a plain-language summary of the intervention
#'   effect.
#' @param showExplanation Display an explanation of the segmented regression
#'   methodology.
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$todo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$coefTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$effectTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$diagnostics} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$explanation} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$coefTable$asDF}
#'
#' \code{as.data.frame(results$coefTable)}
#'
#' @export
interruptedtimeseries <- function(
    data,
    time,
    outcome,
    interventionTime = 0,
    hac = TRUE,
    lag = 0,
    counterfactual = TRUE,
    predictAt = 0,
    showDiagnostics = TRUE,
    showPlot = TRUE,
    showSummary = FALSE,
    showExplanation = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("interruptedtimeseries requires jmvcore to be installed (restart may be required)")

    if ( ! missing(time)) time <- jmvcore::resolveQuo(jmvcore::enquo(time))
    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(time), time, NULL),
            `if`( ! missing(outcome), outcome, NULL))


    options <- interruptedtimeseriesOptions$new(
        time = time,
        outcome = outcome,
        interventionTime = interventionTime,
        hac = hac,
        lag = lag,
        counterfactual = counterfactual,
        predictAt = predictAt,
        showDiagnostics = showDiagnostics,
        showPlot = showPlot,
        showSummary = showSummary,
        showExplanation = showExplanation)

    analysis <- interruptedtimeseriesClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

